QZ(40, 3, "Transductores de Pila (PDT) y Analizadores LR", [
  VF("En general, cuando se adiciona alguna capacidad de cómputo a un Analizador LR, las acciones se llevan a cabo durante la operación de Shifting (desplazamiento).", false, "Se llevan a cabo al reducir."),
  VF("Al definir un PDT como DETERMINISTA, NO se permitirán transiciones o salidas con READ y POP simultáneamente nulas, NI cualquier otra situación que conduzca a más de una reacción para un estímulo dado.", true),
  FL("Dado el siguiente PDT, escribir la salida, sin espacios en blanco, correspondiente a la entrada: <b>acccaaccbbccbcccc</b>", [{ k: "Salida", a: ["aaabbb"] }], "Imprime a por cada a (apilando) e imprime b por cada b (desapilando); las c no imprimen.", "q40pdt"),
  VF("En general un Analizador LR realiza 2 operaciones: Reduction (reducción) y Shifting (desplazamiento).", true),
  VF("El modelo conversor de expresiones aritméticas entrefijas a posfijas rechaza las secuencias que no poseen paréntesis balanceados.", true),
  VF("Para implementar el Analizador LR(k) se construye un AF a partir de las reglas de la gramática, que reconoce los patrones correspondientes a las partes derechas de dichas reglas. Los estados de este AF se consideran símbolos especiales que se van cargando en la pila del AP junto con el símbolo de la parte derecha de la regla que corresponde a la transición del AF, comenzando con el estado inicial del AF en la pila. A partir de este AF se construye la Tabla de Análisis LR.", true),
  MT("Emparejar las siguientes gramáticas de análisis SLR(1) con las Tablas de Análisis correspondientes.<br><b>G1:</b> S → abS | bS | a<br><b>G2:</b> S → aaS | a | bSb<br><b>G3:</b> S → bbS | Saa | λ", [["Tabla 1", "G3"], ["Tabla 2", "G2"], ["Tabla 3", "G1"]], ["G1", "G2", "G3"], "", "q40tab"),
  FL("Dada la siguiente expresión aritmética en notación entrefija (infija), escribir su equivalente posfija sin espacios en blanco: <b>(a+b)*(b+c*a)</b>", [{ k: "Posfija", a: ["ab+bca*+*"] }]),
  VF("Podemos decir que una MEF es un AFD al que se le agregó una función de salida. De igual modo se puede definir un Transductor de Pila (PushDown Transducer, PDT) como un APD al que se le agrega una función de salida. Esta salida, definida sobre un alfabeto de salida Σ_{S}, tiene en general el mismo dominio que la función de transición del APD y el rango en Σ_{S}*. De tal modo, en cada transición puede escribir una secuencia de símbolos en una cinta de salida infinita, que eventualmente puede ser la palabra vacía.", true),
  VF("Un Transductor de Pila o PDT (Push Down Transducer) es un APD al que se le agrega una cinta finita de salida, donde puede escribir secuencias de un alfabeto de salida Σ_{S}.", false, "La cinta de salida es infinita."),
  VF("La notación posfija de una expresión aritmética no siempre lleva un operador al final.", false),
  VF("En una expresión aritmética en notación posfija eventualmente pueden aparecer paréntesis para priorizar el orden de evaluación de los operadores.", false),
  MT("Los analizadores LR(K) son modelos de … diseñados a partir de una gramática … del contexto, con criterio de análisis ascendente con derivaciones …, que recorren la secuencia de entrada desde la … y en general utilizan el principio de «preanálisis», anticipando la lectura de K símbolos de entrada sin «consumirlos». El caso más simple es con K = 1 y se los conoce como SLR(1).", [["modelos de…", "autómata de pila", ["autómata de pila", "autómata finito", "máquina de Turing"]], ["gramática…", "independiente", ["independiente", "dependiente", "regular"]], ["derivaciones…", "más a la derecha", ["más a la derecha", "más a la izquierda"]], ["recorren la entrada desde la…", "izquierda", ["izquierda", "derecha"]]])
]);

QZ(41, 4, "MT especiales · LRE y LRec · Computabilidad y complejidad", [
  MT("Emparejar las siguientes características con la MT correspondiente.", [["Tienen varios cabezales que se mueven en forma conjunta.", "MT Multipista"], ["Inicialmente en cada celda se carga una tupla de símbolos.", "MT Multipista"], ["Inicialmente la secuencia a procesar se encuentra en la primera cinta.", "MT Multicinta"], ["Tienen varios cabezales que se mueven en forma independiente.", "MT Multicinta"]], ["MT Simple", "MT Multipista", "MT Multicinta"], "Las MT multicinta y multipista son variaciones que facilitan la resolución de determinados problemas, pero tienen el mismo potencial que las MT normales de una cinta."),
  MT("La Teoría de la Complejidad Computacional es la rama de la teoría de la computación que estudia, de manera teórica, la complejidad inherente a la resolución de un problema computable. Relacione los recursos comúnmente estudiados con sus explicaciones:", [["Se hace una aproximación a la cantidad de memoria utilizada para resolver un problema.", "El espacio"], ["Se pueden estudiar otros parámetros, tales como el número de procesadores necesarios para resolver el problema en paralelo.", "Parámetros varios"], ["Se estudia mediante una aproximación al número y tipo de pasos de ejecución de un algoritmo para resolver un problema.", "El tiempo"]]),
  MT("Dada la siguiente MT, completar con la respuesta correcta:", [["Funciona como una MT tipo…", "Multicinta", ["Multicinta", "Multipista", "Simple", "En bloques"]], ["Acepta el lenguaje…", "a^n b^n c^n d^n", ["a^n b^n c^n d^n", "a^n b^n c^n", "a^n b^m c^m d^n", "(abcd)^n"]]], null, "", "q41a"),
  MT("Dada la siguiente MT, completar con la respuesta correcta:", [["Funciona como una MT tipo…", "Multipista", ["Multicinta", "Multipista", "Simple", "En bloques"]], ["Acepta el lenguaje de códigos binarios resolviendo la operación de…", "suma", ["suma", "resta", "multiplicación", "incremento"]]], null, "", "q41b"),
  MT("Dado el problema del Castor Afanoso, la función Σ(n) representa la complejidad … y la función S(n) representa la complejidad …", [["Σ(n):", "Espacial", ["Espacial", "Temporal"]], ["S(n):", "Temporal", ["Espacial", "Temporal"]]], null, "Las dos funciones del Castor Afanoso se usan para mostrar los límites de la complejidad y la computabilidad algorítmica (ambas crecen más rápido que cualquier función computable)."),
  MC("En su tesis, Alan Mathison Turing realizó una prueba conocida como «el problema de la parada o detención de la MT» (The Halting Problem), con la cual demostró que no todo problema bien definido tiene solución algorítmica. ¿Cuál de los siguientes problemas de lenguajes formales no tiene solución algorítmica general?", ["Obtener el complemento de un ALL", "Ninguno", "Encontrar el equivalente determinista de una MT no determinista", "Determinar si una GIC es ambigua."], 3),
  XX("¿De qué forma se puede representar la semántica de un lenguaje de programación?", ["Diagrama de Sintaxis", "Esquemas de Traducción", "Sistemas Canónicos", "Forma Normal de Backus"], [1, 2]),
  XX("Para representar solamente el nivel sintáctico y/o léxico de un lenguaje de programación es suficiente con:", ["Esquemas de Traducción", "Sistemas Canónicos", "Diagramas de Sintaxis", "Forma Normal de Backus"], [2, 3]),
  MC("Esta teoría es la encargada de definir los criterios básicos para saber si un problema computable es factible, dicho de otro modo, si existe un algoritmo eficiente para su resolución y en este caso cuál es su grado de eficiencia. ¿A qué teoría se refiere?", ["Complejidad algorítmica", "Computabilidad", "Lenguajes Recursivamente Enumerables", "Medidas de Complejidad"], 0),
  MC("¿Qué lenguajes se puede afirmar que son cerrados para las operaciones de intersección, unión, concatenación y estrella de Kleene, y no así para el complemento?", ["Ninguno", "Recursivamente enumerables", "Recursivos", "Regulares"], 1),
  VF("Un lenguaje recursivamente enumerable es un lenguaje formal para el cual existe una máquina de Turing que acepta y se detiene con cualquier cadena del lenguaje, pero que puede parar y rechazar, o bien iterar indefinidamente, con una cadena que no pertenece al lenguaje; en contraposición a los lenguajes recursivos, en cuyo caso se requiere que la máquina de Turing pare en todos los casos.", true),
  VF("Un lenguaje es recursivo si es aceptado por una máquina de Turing que se detiene para todo input.", true),
  VF("Un lenguaje L es recursivo si es decidible por alguna máquina de Turing.", true),
  VF("Los lenguajes regulares, independientes de contexto y dependientes de contexto son lenguajes recursivos.", true),
  VF("Todo lenguaje recursivo no es necesariamente recursivamente enumerable.", false, "Todo lenguaje recursivo es recursivamente enumerable."),
  VF("La teoría de la complejidad difiere de la teoría de la computabilidad en que esta última se ocupa de la factibilidad de expresar problemas como algoritmos efectivos sin tomar en cuenta los recursos necesarios para ello.", true),
  VF("Las MT Multipista se utilizan a menudo para realizar operaciones aritméticas.", true, "Se suelen colocar los operandos en las primeras pistas y obtener el resultado en la última."),
  VF("Las MT Multicinta facilitan el reconocimiento de patrones sin modificar la secuencia de entrada, utilizando las otras cintas para escribir las «marcas» que se deseen en correspondencia con los símbolos de la cinta de entrada, sin necesidad de sobrescribirlos.", true)
]);

QZ(42, 4, "MT y ALL", [
  MC("Dado el siguiente ALL, indicar el lenguaje que acepta.", ["Todas las secuencias sobre {a, b} que tienen el doble de «b» que de «a».", "Todas las secuencias sobre {a, b} que tienen igual cantidad de «a» que de «b», excepto la palabra vacía.", "Todas las secuencias sobre {a, b} que tienen igual cantidad de «a» que de «b», incluso la palabra vacía.", "Todas las secuencias sobre {a, b} que tienen el doble de «a» que de «b».", "Todas las palabras sobre {a, b} que tienen mayor cantidad de «a» que de «b», más la palabra vacía."], 2, "", "q42a"),
  MC("Dada la siguiente MT transformadora, analice su funcionamiento. Diga qué secuencia queda en la cinta al detenerse y en qué posición queda el cabezal, si parte de una cinta en blanco.", ["Una secuencia de 8 unos consecutivos y el cabezal en el quinto uno.", "Una secuencia de 6 unos consecutivos y el cabezal sobre el cuarto uno.", "Queda en blanco y el cabezal en la posición inicial.", "Una secuencia de 3 unos con espacios intercalados y el cabezal al principio.", "Una secuencia de 6 unos consecutivos y el cabezal al final."], 1, "Es un «castor afanoso» de 3 estados.", "q42b"),
  VF("Un Autómata con Limitación Lineal (ALL) utiliza como máximo la cantidad de casilleros que ocupa la secuencia inicial de entrada y siempre termina deteniéndose, sin importar la secuencia que se introduzca.", true),
  VF("Toda Máquina de Turing aceptora de un lenguaje termina transformando la secuencia de entrada, de tal modo que difiere de la secuencia inicial.", false),
  VF("Dada una MT y una secuencia de entrada, después de un número finito de transiciones la MT se detiene en un estado final de aceptación o se bloquea rechazando la secuencia.", false, "Puede no detenerse nunca."),
  VF("Toda Máquina de Turing transformadora de secuencias también es aceptora de algún lenguaje.", true),
  VF("Una MT transformadora de secuencias solo puede resolver problemas matemáticos de cálculo.", false),
  VF("Para todo AF es posible diseñar una MT que acepte el mismo lenguaje.", true),
  VF("Las MT pueden ser aceptoras y/o transformadoras, pero los ALL pueden ser solamente aceptores.", false),
  VF("Para toda MT aceptora es posible diseñar un AP que acepte el mismo lenguaje.", false),
  XX("Indicar cuáles de estos modelos aceptan el mismo lenguaje.", ["1", "2", "3", "4"], [0, 2], "", "q42c"),
  XX("Indicar cuáles de las siguientes máquinas aceptan el lenguaje a^n b^m / m ≥ 0, n &gt; m+1.", ["1", "2", "3", "4"], [1, 3], "", "q42d")
]);

QZ(43, 4, "Análisis semántico · Esquemas de traducción · CUP", [
  MT("Dado el Esquema de Traducción del Lenguaje Hipotético visto en clase, emparejar las secuencias de aplicación de las acciones semánticas con el programa que corresponda.", [["Secuencia 1", "float id ; { id = real }"], ["Secuencia 2", "boolean id ; { break }"], ["Secuencia 3", "boolean id ; { while cierto do { break } }"], ["Secuencia 4", "boolean id ; { id = real }"]], null, "Secuencia 2 termina con S.BIFU = error.b (break fuera de un bucle) y la 4 con S.TIPO = error.t (se asigna real a un boolean).", "q43seq"),
  MT("El metacompilador CUP permite implementar un Esquema de Traducción. El mismo utiliza un criterio de análisis … con derivaciones más a la …. En ese proceso se realizan operaciones de …. Las acciones semánticas se llevan a cabo en el momento de …", [["criterio de análisis…", "ascendente", ["ascendente", "descendente"]], ["derivaciones más a la…", "derecha", ["derecha", "izquierda"]], ["operaciones de…", "desplazamiento y reducción", ["desplazamiento y reducción", "sustitución", "factorización"]], ["las acciones se llevan a cabo en…", "una reducción", ["una reducción", "un desplazamiento", "la lectura de un token"]]], null, "En el intento, «sustitución» fue marcado incorrecto."),
  MT("¿Cómo se usan los esquemas de traducción en un proceso de análisis de una sentencia? Depende del criterio de análisis: descendente con derivaciones más a la … o ascendente con derivaciones más a la …. En ambos casos los fragmentos de programa utilizan variables que en general constituyen atributos de los … de la gramática, que se asocian con las restricciones … que se tienen que verificar. En el análisis descendente se dice que los atributos son …, ya que se obtienen a partir de los atributos de los nodos …. En el ascendente se dice que son …, ya que se obtienen a partir de los atributos de los nodos …", [["descendente, más a la…", "izquierda", ["izquierda", "derecha"]], ["ascendente, más a la…", "derecha", ["izquierda", "derecha"]], ["atributos de los…", "No-Terminales", ["No-Terminales", "Terminales", "estados"]], ["restricciones…", "semánticas", ["semánticas", "sintácticas", "léxicas"]], ["en el descendente los atributos son…", "heredados", ["heredados", "sintetizados"]], ["a partir de los nodos…", "padres", ["padres", "hijos"]], ["en el ascendente los atributos son…", "sintetizados", ["heredados", "sintetizados"]], ["a partir de los nodos… ", "hijos", ["padres", "hijos"]]]),
  XX("Indique las comprobaciones que correspondan al nivel semántico de un lenguaje de programación.", ["Coherencia entre tipos de datos y operadores en una expresión.", "La estructura sintáctica de una sentencia repetitiva.", "Expresión lógica en las condiciones de las estructuras de control selectivas y repetitivas.", "El reconocimiento de las palabras reservadas.", "El reconocimiento de los identificadores válidos.", "La bifurcación incondicional GOTO debe tener su rótulo de referencia dentro de la lista de rótulos de enunciados.", "La estructura sintáctica de una sentencia selectiva.", "La bifurcación incondicional BREAK debe estar dentro de un anidamiento de estructuras repetitivas o selectivas."], [0, 2, 5, 7]),
  VF("Toda regla de una GIC, en un Esquema de Traducción, tiene asociada una o varias acciones semánticas.", false),
  VF("Puede haber acciones semánticas de inicialización, que se ejecutan al inicio del proceso de análisis y no están asociadas a ninguna regla de la GIC.", true),
  VF("Un Esquema de Traducción tiene en cuenta aspectos léxicos, sintácticos y semánticos de un lenguaje de programación.", true, "Un esquema de traducción consiste en una GIC ampliada con especificaciones semánticas para algunas de sus reglas."),
  VF("Un Esquema de Traducción es una gramática independiente del contexto en la que se agrega, a la derecha de algunas reglas de producción, un fragmento de programa llamado Acción Semántica.", true)
]);

QZ(44, 4, "MT multipista, multicinta y MT en bloques", [
  MT("Indicar a qué tipo de modelo corresponde cada grafo.", [["Grafo 1 (M5)", "Máquina de Turing Simple"], ["Grafo 2 (M14)", "Máquina de Turing Multipista"], ["Grafo 3 (M1)", "Máquina de Turing Multicinta"], ["Grafo 4 (M9)", "Autómata con Limitación Lineal"]], ["Máquina de Turing Simple", "Máquina de Turing Multipista", "Máquina de Turing Multicinta", "Autómata con Limitación Lineal"], "M1 mueve dos cabezales de forma independiente (S en una cinta, R o L en la otra): es multicinta. M14 mueve las dos pistas juntas. M9 trabaja entre los delimitadores &lt; &gt;: es un ALL.", "q44mod"),
  MC("Dada la siguiente MT construida con los bloques MT1, MT2, MT3, MT4 y MT5, analizar su funcionamiento e indicar cuál es la salida que se obtiene para una secuencia inicial β:", ["ββ0", "β^{-1}β0", "β0β", "0β^{-1}0β", "β0β0β"], 2, "", "q44blq"),
  VF("Las MT multipista tienen varias pistas y cada pista tiene un cabezal que se puede mover independientemente de los cabezales de las otras pistas.", false, "Eso describe a las multicinta; en la multipista los cabezales se mueven juntos."),
  VF("Para toda MT multipista o multicinta se puede encontrar una MT simple equivalente, es decir, con una sola cinta y una sola pista.", true)
]);
